mapper.update:
update `team_task`
name = #{name}, content = #{content}, type = #{type}, assignee_type = #{assigneeType}, start_time = #{startTime}, end_time = #{endTime}, reward = #{reward},
where id = #{id}

mapper.delete:
delete from `team_task_assignee`
where user_id = #{userId}
  and task_id in (select id from `team_task` where team_id = #{teamId})

delete from `team_task_completion`
where user_id = #{userId}
  and task_id in (select id from `team_task` where team_id = #{teamId})
